-- Base de données D1 du site (à coller une seule fois dans la console D1 de Cloudflare)
CREATE TABLE IF NOT EXISTS compteurs (nom TEXT PRIMARY KEY, valeur INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reglages  (cle TEXT PRIMARY KEY, valeur TEXT);
CREATE TABLE IF NOT EXISTS messages  (id INTEGER PRIMARY KEY AUTOINCREMENT, nom TEXT NOT NULL, texte TEXT NOT NULL, cree INTEGER NOT NULL, statut TEXT NOT NULL DEFAULT 'attente');
CREATE TABLE IF NOT EXISTS limites   (cle TEXT PRIMARY KEY, dernier INTEGER NOT NULL);
INSERT OR IGNORE INTO compteurs (nom, valeur) VALUES ('mauruuru', 0), ('clic:discord', 0), ('clic:insta', 0);
INSERT OR IGNORE INTO reglages (cle, valeur) VALUES ('statut', '');
CREATE TABLE IF NOT EXISTS liens (id INTEGER PRIMARY KEY AUTOINCREMENT, titre TEXT NOT NULL, sous_titre TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, icone TEXT NOT NULL DEFAULT 'lien', ordre INTEGER NOT NULL DEFAULT 0, actif INTEGER NOT NULL DEFAULT 1, clics INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS raccourcis (code TEXT PRIMARY KEY, url TEXT NOT NULL, clics INTEGER NOT NULL DEFAULT 0, cree INTEGER NOT NULL);
INSERT INTO liens (titre, sous_titre, url, icone, ordre) SELECT 'Me suivre sur Instagram', 'Photos et stories de Tahiti', 'https://www.instagram.com/landry.pf/', 'instagram', 1 WHERE NOT EXISTS (SELECT 1 FROM liens);
INSERT OR IGNORE INTO raccourcis (code, url, clics, cree) VALUES ('insta', 'https://www.instagram.com/landry.pf/', 0, 0);
-- v2
ALTER TABLE liens ADD COLUMN debut INTEGER;
ALTER TABLE liens ADD COLUMN fin INTEGER;
CREATE TABLE IF NOT EXISTS stats_jour (jour TEXT NOT NULL, cle TEXT NOT NULL, valeur INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (jour, cle));
CREATE TABLE IF NOT EXISTS fichiers (id TEXT PRIMARY KEY, nom TEXT NOT NULL, cle TEXT NOT NULL, type TEXT NOT NULL, taille INTEGER NOT NULL, cree INTEGER NOT NULL, telechargements INTEGER NOT NULL DEFAULT 0, mdp TEXT, expire INTEGER, galerie INTEGER NOT NULL DEFAULT 0, legende TEXT NOT NULL DEFAULT '', ordre INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY AUTOINCREMENT, nom TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', message TEXT NOT NULL, cree INTEGER NOT NULL, lu INTEGER NOT NULL DEFAULT 0);
ALTER TABLE fichiers ADD COLUMN vu_galerie INTEGER NOT NULL DEFAULT 0;
-- v5
ALTER TABLE fichiers ADD COLUMN album INTEGER NOT NULL DEFAULT 0;
ALTER TABLE messages ADD COLUMN reactions INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS blocs (id INTEGER PRIMARY KEY AUTOINCREMENT, url TEXT NOT NULL, type TEXT NOT NULL, ref TEXT NOT NULL, ordre INTEGER NOT NULL DEFAULT 0, actif INTEGER NOT NULL DEFAULT 1, cree INTEGER NOT NULL);

-- v18 : outils (transferts, bloc-notes, liens courts avancés)
CREATE TABLE IF NOT EXISTS transferts (id TEXT PRIMARY KEY, titre TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', mdp TEXT, expire INTEGER, max_dl INTEGER, dl INTEGER NOT NULL DEFAULT 0, notifier INTEGER NOT NULL DEFAULT 0, cree INTEGER NOT NULL, fini INTEGER, supprime INTEGER, vide INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS transfert_fichiers (id TEXT PRIMARY KEY, transfert TEXT NOT NULL, nom TEXT NOT NULL, cle TEXT NOT NULL, type TEXT NOT NULL, taille INTEGER NOT NULL, crc INTEGER NOT NULL DEFAULT 0, cree INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS transfert_dl (transfert TEXT NOT NULL, quand INTEGER NOT NULL, quoi TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY, titre TEXT NOT NULL DEFAULT '', texte TEXT NOT NULL, mdp TEXT, expire INTEGER, unique_lecture INTEGER NOT NULL DEFAULT 0, lu INTEGER, vues INTEGER NOT NULL DEFAULT 0, cree INTEGER NOT NULL, supprime INTEGER);
ALTER TABLE raccourcis ADD COLUMN url_ios TEXT;
ALTER TABLE raccourcis ADD COLUMN url_android TEXT;
ALTER TABLE raccourcis ADD COLUMN expire INTEGER;
ALTER TABLE raccourcis ADD COLUMN max_clics INTEGER;
CREATE TABLE IF NOT EXISTS clics_jour (code TEXT NOT NULL, jour TEXT NOT NULL, appareil TEXT NOT NULL, pays TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (code, jour, appareil, pays));
